CREATE POLICY "agendamento_access" ON public."agendamento" AS PERMISSIVE FOR ALL TO authenticated USING ((is_super_admin() OR has_company_access(company_id))) WITH CHECK ((is_super_admin() OR has_company_access(company_id)));
