CREATE POLICY "company_user_delete" ON public."company_user" AS PERMISSIVE FOR DELETE TO authenticated USING ((is_super_admin() OR has_company_access(company_id)));
CREATE POLICY "company_user_insert" ON public."company_user" AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((is_super_admin() OR has_company_role(company_id, ARRAY['owner'::text, 'admin'::text]) OR ((user_id = auth.uid()) AND (role = 'owner'::tenant_role) AND (EXISTS ( SELECT 1
   FROM company c
  WHERE ((c.id = company_user.company_id) AND (c.created_by = auth.uid())))) AND (NOT (EXISTS ( SELECT 1
   FROM company_user existing
  WHERE (existing.company_id = company_user.company_id)))))));
CREATE POLICY "company_user_select" ON public."company_user" AS PERMISSIVE FOR SELECT TO authenticated USING ((is_super_admin() OR (user_id = auth.uid()) OR has_company_access(company_id)));
