CREATE POLICY "profiles_company_admin_select" ON public."profiles" AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM (company_user me
     JOIN company_user target ON ((target.company_id = me.company_id)))
  WHERE ((me.user_id = auth.uid()) AND (me.ativo = true) AND (me.role = ANY (ARRAY['owner'::tenant_role, 'admin'::tenant_role])) AND (target.user_id = profiles.user_id) AND (target.ativo = true)))));
CREATE POLICY "profiles_insert" ON public."profiles" AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((user_id = auth.uid()));
CREATE POLICY "profiles_select" ON public."profiles" AS PERMISSIVE FOR SELECT TO authenticated USING (((user_id = auth.uid()) OR is_super_admin()));
